import redis
from collections import Counter
for db in range(16):
 a=redis.Redis(host='127.0.0.1',port=6379,db=db)
 b=redis.Redis(host='127.0.0.1',port=6380,db=db)
 ka=set(a.scan_iter());kb=set(b.scan_iter())
 assert ka==kb,(db,len(ka),len(kb),len(ka^kb))
 types=Counter()
 for k in ka:
  t=a.type(k); types[t.decode()]+=1
  assert t==b.type(k),(db,k,'type')
  at=a.pexpiretime(k);bt=b.pexpiretime(k)
  assert at==bt,(db,k,'expiry',at,bt)
  if t==b'string': x=a.get(k); y=b.get(k)
  elif t==b'list': x=a.lrange(k,0,-1);y=b.lrange(k,0,-1)
  elif t==b'set': x=a.smembers(k);y=b.smembers(k)
  elif t==b'zset': x=a.zrange(k,0,-1,withscores=True);y=b.zrange(k,0,-1,withscores=True)
  elif t==b'hash': x=a.hgetall(k);y=b.hgetall(k)
  elif t==b'stream':
   x=a.xrange(k);y=b.xrange(k)
   assert a.xinfo_stream(k)==b.xinfo_stream(k),(db,k,'stream metadata')
   ga=a.xinfo_groups(k);gb=b.xinfo_groups(k)
   assert ga==gb,(db,k,'groups',ga,gb)
   for g in ga:
    name=g['name'];assert a.xinfo_consumers(k,name)==b.xinfo_consumers(k,name),(db,k,name,'consumers')
    assert a.xpending_range(k,name,'-','+',100000)==b.xpending_range(k,name,'-','+',100000),(db,k,name,'pending')
  else: raise Exception((db,k,t))
  assert x==y,(db,k,'value')
 if ka: print('db',db,len(ka),dict(types),'OK')
print('All databases match')
